//! URL scheme registration (`[ui] handle_links`).
//!
//! - Windows: a ProgId plus an application "Capabilities" registration under HKCU, so Siple
//!   shows up under Default apps for `sip`, `sips`, `tel`, `callto` and `siple` and the user
//!   chooses (Windows does not let an app take over a scheme silently). `siple:` is Siple's own
//!   scheme and nothing else claims it, so it also gets a direct class (a Capabilities entry
//!   alone does not make an unclaimed scheme launchable). Content generated by
//!   [`windows_entries`] (pure), applied with `winreg`.
//! - macOS: `CFBundleURLTypes` in `Info.plist` (packaging) and an Apple Event handler in the
//!   running app (`platform::macos`); nothing to do at runtime.
//! - Linux: `MimeType=x-scheme-handler/...` in the `.desktop` file and `xdg-mime default` at
//!   install time (packaging); the app does not run `xdg-mime`.

use std::path::Path;

use siple_core::config::APP_ID;

/// Schemes Siple handles.
#[cfg_attr(not(target_os = "windows"), allow(dead_code))]
pub const SCHEMES: [&str; 5] = ["sip", "sips", "tel", "callto", "siple"];

/// One registry value: `(key path under HKCU, value name ("" = default), data)`.
#[cfg_attr(not(target_os = "windows"), allow(dead_code))]
pub type RegValue = (String, String, String);

/// Everything to write under HKCU to register Siple as a link handler for `exe`.
#[cfg_attr(not(target_os = "windows"), allow(dead_code))]
pub fn windows_entries(exe: &Path) -> Vec<RegValue> {
    let exe = exe.to_string_lossy();
    let prog = format!(r"Software\Classes\{APP_ID}.url");
    let caps = format!(r"Software\{APP_ID}\Capabilities");
    let mut v = vec![
        (prog.clone(), String::new(), "URL: SIP / tel link".into()),
        (prog.clone(), "URL Protocol".into(), String::new()),
        (
            format!(r"{prog}\DefaultIcon"),
            String::new(),
            format!("\"{exe}\",0"),
        ),
        (
            format!(r"{prog}\shell\open\command"),
            String::new(),
            format!("\"{exe}\" -- \"%1\""),
        ),
        // The direct class of `siple:` (setup links), opened as `siple.exe -- "%1"`.
        (
            r"Software\Classes\siple".into(),
            String::new(),
            "URL:Siple setup link".into(),
        ),
        (
            r"Software\Classes\siple".into(),
            "URL Protocol".into(),
            String::new(),
        ),
        (
            r"Software\Classes\siple\DefaultIcon".into(),
            String::new(),
            format!("\"{exe}\",0"),
        ),
        (
            r"Software\Classes\siple\shell\open\command".into(),
            String::new(),
            format!("\"{exe}\" -- \"%1\""),
        ),
        (caps.clone(), "ApplicationName".into(), "Siple".into()),
        (
            caps.clone(),
            "ApplicationDescription".into(),
            "Siple softphone".into(),
        ),
        (
            r"Software\RegisteredApplications".into(),
            "Siple".into(),
            caps.clone(),
        ),
    ];
    for s in SCHEMES {
        v.push((
            format!(r"{caps}\URLAssociations"),
            s.into(),
            format!("{APP_ID}.url"),
        ));
    }
    v
}

/// Keys to delete (recursively) to unregister, deepest-last is not required.
#[cfg_attr(not(target_os = "windows"), allow(dead_code))]
pub fn windows_keys_to_remove() -> Vec<String> {
    vec![
        format!(r"Software\Classes\{APP_ID}.url"),
        r"Software\Classes\siple".to_string(),
        format!(r"Software\{APP_ID}"),
    ]
}

/// Registers (`enabled`) or unregisters the handler. A no-op outside Windows, and in packaged
/// editions (MSIX declares the protocols in its manifest; an HKCU entry would point at the
/// versioned package path and break on update).
pub fn apply(enabled: bool) -> std::io::Result<()> {
    apply_for(siple_core::config::channel::current(), enabled)
}

fn apply_for(channel: &siple_core::config::channel::Channel, enabled: bool) -> std::io::Result<()> {
    if channel.is_packaged() {
        tracing::info!(
            channel = channel.kind.as_str(),
            enabled,
            "link handler registration is managed by the package; nothing to do"
        );
        return Ok(());
    }
    #[cfg(target_os = "windows")]
    {
        use winreg::RegKey;
        use winreg::enums::{HKEY_CURRENT_USER, KEY_SET_VALUE};
        let hkcu = RegKey::predef(HKEY_CURRENT_USER);
        if enabled {
            let exe = std::env::current_exe()?;
            for (key, name, data) in windows_entries(&exe) {
                let (k, _) = hkcu.create_subkey(&key)?;
                k.set_value(&name, &data)?;
            }
            return Ok(());
        }
        for key in windows_keys_to_remove() {
            match hkcu.delete_subkey_all(&key) {
                Err(e) if e.kind() != std::io::ErrorKind::NotFound => return Err(e),
                _ => {}
            }
        }
        let ra = hkcu.open_subkey_with_flags(r"Software\RegisteredApplications", KEY_SET_VALUE);
        if let Ok(ra) = ra {
            match ra.delete_value("Siple") {
                Err(e) if e.kind() != std::io::ErrorKind::NotFound => return Err(e),
                _ => {}
            }
        }
        Ok(())
    }
    #[cfg(not(target_os = "windows"))]
    {
        let _ = enabled;
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn packaged_editions_skip_registration() {
        use siple_core::config::channel::Channel;
        // Returns before touching the registry (a Windows run would otherwise write HKCU).
        assert!(apply_for(&Channel::msix("a_b", None), true).is_ok());
        assert!(apply_for(&Channel::MAC_APP_STORE, true).is_ok());
    }

    #[test]
    fn registry_entries_cover_every_scheme_and_quote_the_path() {
        let e = windows_entries(Path::new(r"C:\Program Files\Siple\siple.exe"));
        let find = |k: &str, n: &str| {
            e.iter()
                .find(|(kk, nn, _)| kk == k && nn == n)
                .map(|x| x.2.clone())
        };
        assert_eq!(
            find(r"Software\Classes\io.zyno.siple.url\shell\open\command", "").unwrap(),
            r#""C:\Program Files\Siple\siple.exe" -- "%1""#
        );
        assert_eq!(
            find(r"Software\Classes\io.zyno.siple.url", "URL Protocol").unwrap(),
            ""
        );
        for s in SCHEMES {
            assert_eq!(
                find(r"Software\io.zyno.siple\Capabilities\URLAssociations", s).unwrap(),
                "io.zyno.siple.url"
            );
        }
        assert_eq!(
            find(r"Software\RegisteredApplications", "Siple").unwrap(),
            r"Software\io.zyno.siple\Capabilities"
        );
        // Only HKCU-relative keys; nothing machine-wide.
        assert!(e.iter().all(|(k, _, _)| k.starts_with("Software\\")));
        // The direct `siple:` class.
        assert_eq!(
            find(r"Software\Classes\siple\shell\open\command", "").unwrap(),
            r#""C:\Program Files\Siple\siple.exe" -- "%1""#
        );
        assert_eq!(find(r"Software\Classes\siple", "URL Protocol").unwrap(), "");
        assert!(
            windows_keys_to_remove()
                .iter()
                .all(|k| k.contains("io.zyno.siple") || k == r"Software\Classes\siple")
        );
        assert!(windows_keys_to_remove().contains(&r"Software\Classes\siple".to_string()));
    }
}
